class Solution {public int solve(int[][] grid){int m=grid.length,n=m==0?0:grid[0].length;boolean[][] seen=new boolean[m][n];HashSet<String> shapes=new HashSet<>();int[] dr={-1,1,0,0},dc={0,0,-1,1};for(int r=0;r<m;r++)for(int c=0;c<n;c++)if(grid[r][c]==1&&!seen[r][c]){ArrayList<int[]> q=new ArrayList<>(),points=new ArrayList<>();q.add(new int[]{r,c});seen[r][c]=true;for(int i=0;i<q.size();i++){int[] p=q.get(i);points.add(new int[]{p[0]-r,p[1]-c});for(int k=0;k<4;k++){int x=p[0]+dr[k],y=p[1]+dc[k];if(x>=0&&x<m&&y>=0&&y<n&&grid[x][y]==1&&!seen[x][y]){seen[x][y]=true;q.add(new int[]{x,y});}}}points.sort((a,b)->a[0]!=b[0]?Integer.compare(a[0],b[0]):Integer.compare(a[1],b[1]));StringBuilder s=new StringBuilder();for(int[] p:points)s.append(p[0]).append(',').append(p[1]).append(';');shapes.add(s.toString());}return shapes.size();}}